    same(r.size, 'cpuCount')
  })
  check('I/O 密集 → 线程池，可多开等 I/O', () => {
    const r = recommendModel({ workload: 'io' })
    same(r.model, 'thread-pool')
    same(r.size, 'io-bound')
  })
