function effectiveAccessTime(p) {
  const hit = p.tlbHitRate * (p.tlbMs + p.memMs)
  const miss = (1 - p.tlbHitRate) * (p.tlbMs + 2 * p.memMs)
  return hit + miss + p.faultRate * p.faultMs
}

